import React, { useState, useEffect, useRef } from 'react';
import Dashboard from './Dashboard';
import Enrollment from './Enrollment';
import CameraRecognition from './CameraRecognition';
import Login from './pages/Login';
import authService from './auth_service';
import { studentsAPI } from './api_service';

const COLORS = {
  primary: '#4F46E5',
  background: '#F8FAFC',
  surface: '#FFFFFF',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  sidebar: '#1E293B'
};

const App = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  const [currentView, setCurrentView] = useState('dashboard');
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);

  // ================= SEARCH STATES =================
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [showResults, setShowResults] = useState(false);

  const debounceRef = useRef(null);

  // ================= INIT AUTH =================
  useEffect(() => {
    authService.initialize();

    if (authService.isAuthenticated()) {
      setCurrentUser(authService.getUser());
      setIsAuthenticated(true);
    }

    setLoading(false);
  }, []);

  // ================= NOTIFICATIONS =================
  const addNotification = (message, type = 'info') => {
    const id = Date.now();
    setNotifications(prev => [...prev, { id, message, type }]);

    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 4000);
  };

  // ================= SEARCH WITH DEBOUNCE =================
  const handleSearch = (value) => {
    setSearchQuery(value);

    if (debounceRef.current) {
      clearTimeout(debounceRef.current);
    }

    if (value.trim().length < 2) {
      setSearchResults([]);
      setShowResults(false);
      return;
    }

    debounceRef.current = setTimeout(async () => {
      try {
        const response = await studentsAPI.search(value);

        // ✅ CORRECTION: Vérifier et convertir le format des résultats
        let resultsArray = [];

        if (Array.isArray(response)) {
          resultsArray = response;
        } else if (response?.data && Array.isArray(response.data)) {
          resultsArray = response.data;
        } else if (response?.data?.results && Array.isArray(response.data.results)) {
          resultsArray = response.data.results;
        } else if (response?.data?.students && Array.isArray(response.data.students)) {
          resultsArray = response.data.students;
        }

        // Protection supplémentaire
        const safeResults = Array.isArray(resultsArray) ? resultsArray : [];

        setSearchResults(safeResults);
        setShowResults(safeResults.length > 0);

      } catch (error) {
        console.error('❌ Erreur recherche:', error);
        setSearchResults([]);
        setShowResults(false);
        addNotification('❌ Erreur de recherche serveur', 'error');
      }
    }, 400);
  };

  // ================= SELECT RESULT =================
  const handleSelectStudent = (student) => {
    if (!student || typeof student !== 'object') return;

    const studentName = String(student.name || student.full_name || 'Inconnu').trim();
    setSearchQuery(studentName);
    setShowResults(false);
    addNotification(`👤 Étudiant sélectionné: ${studentName}`, 'info');
  };

  // ================= LOGIN =================
  const handleLoginSuccess = (user) => {
    setCurrentUser(user);
    setIsAuthenticated(true);
    addNotification(`✅ Bienvenue ${user.first_name || user.username || 'Utilisateur'}`, 'success');
  };

  // ================= LOGOUT =================
  const handleLogout = async () => {
    await authService.logout();
    setCurrentUser(null);
    setIsAuthenticated(false);
    setSearchQuery('');
    setSearchResults([]);
    addNotification('👋 Déconnexion réussie', 'info');
  };

  if (loading) {
    return <div style={styles.loading}>⏳ Chargement...</div>;
  }

  if (!isAuthenticated) {
    return <Login onLoginSuccess={handleLoginSuccess} />;
  }

  return (
    <div style={styles.appWrapper}>

      {/* ================= SIDEBAR ================= */}
      <aside style={styles.sidebar}>
        <div style={styles.brand}>
          <div style={styles.brandIcon}>Σ</div>
          <h2 style={styles.brandName}>Attendance OS</h2>
        </div>

        <nav style={styles.sideNav}>
          <NavItem 
            active={currentView === 'dashboard'} 
            onClick={() => setCurrentView('dashboard')} 
            icon="📊" 
            label="Dashboard" 
          />
          <NavItem 
            active={currentView === 'enrollment'} 
            onClick={() => setCurrentView('enrollment')} 
            icon="➕" 
            label="Enrôlement" 
          />
          <NavItem 
            active={currentView === 'camera'} 
            onClick={() => setCurrentView('camera')} 
            icon="📷" 
            label="Reconnaissance" 
          />
        </nav>

        <button onClick={handleLogout} style={styles.logoutBtn}>
          🚪 Déconnexion
        </button>
      </aside>

      {/* ================= MAIN ================= */}
      <main style={styles.main}>

        {/* TOP BAR */}
        <header style={styles.topBar}>

          {/* SEARCH */}
          <div style={{ position: 'relative', width: 420 }}>
            <div style={styles.searchBar}>
              🔍
              <input
                style={styles.searchInput}
                value={searchQuery}
                onChange={(e) => handleSearch(e.target.value)}
                onFocus={() => Array.isArray(searchResults) && searchResults.length > 0 && setShowResults(true)}
                placeholder="Rechercher un étudiant..."
              />
            </div>

            {/* DROPDOWN RESULTS - VERSION CORRIGÉE */}
            {showResults && Array.isArray(searchResults) && searchResults.length > 0 && (
              <div style={styles.dropdown}>
                {searchResults.map((student, index) => {
                  // Protection renforcée contre les objets invalides
                  if (!student || typeof student !== 'object') {
                    return null;
                  }

                  const studentName = String(student.name || student.full_name || 'Inconnu').trim();
                  const studentId = String(student.id || student.student_id || `student-${index}`);

                  return (
                    <div
                      key={`student-${index}-${studentId}`}
                      style={styles.resultItem}
                      onClick={() => handleSelectStudent(student)}
                    >
                      <div style={{ fontWeight: 600 }}>
                        {studentName}
                      </div>
                      <div style={{ fontSize: 12, color: '#64748B' }}>
                        ID: {studentId}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>

        </header>

        {/* CONTENT */}
        <div style={styles.content}>
          {currentView === 'dashboard' && <Dashboard />}
          {currentView === 'enrollment' && <Enrollment />}
          {currentView === 'camera' && <CameraRecognition />}
        </div>
      </main>

      {/* NOTIFICATIONS */}
      <div style={styles.toastContainer}>
        {Array.isArray(notifications) && notifications.map((n) => (
          <div key={n.id} style={styles.toast}>
            {String(n.message)}
          </div>
        ))}
      </div>

    </div>
  );
};

// ================= NAV ITEM =================
const NavItem = ({ active, icon, label, onClick }) => (
  <div 
    onClick={onClick} 
    style={{
      padding: 12,
      cursor: 'pointer',
      color: active ? '#4F46E5' : '#94A3B8',
      fontWeight: 500
    }}
  >
    {icon} {label}
  </div>
);

// ================= STYLES =================
const styles = {
  loading: { 
    height: '100vh', 
    display: 'grid', 
    placeItems: 'center' 
  },

  appWrapper: { display: 'flex' },

  sidebar: {
    width: 260,
    background: '#1E293B',
    color: 'white',
    height: '100vh',
    padding: 20,
    overflowY: 'auto'
  },

  sideNav: {
    marginBottom: 20
  },

  brand: { 
    display: 'flex', 
    gap: 10, 
    marginBottom: 30 
  },

  brandIcon: {
    width: 40,
    height: 40,
    background: '#4F46E5',
    display: 'grid',
    placeItems: 'center',
    borderRadius: 8,
    fontSize: 20,
    fontWeight: 'bold',
    color: 'white'
  },

  brandName: {
    margin: 0,
    fontSize: 18,
    fontWeight: 'bold',
    color: 'white',
    lineHeight: '40px'
  },

  searchBar: {
    display: 'flex',
    gap: 10,
    padding: 10,
    background: '#F1F5F9',
    borderRadius: 8,
    alignItems: 'center'
  },

  searchInput: {
    border: 'none',
    width: '100%',
    outline: 'none',
    background: 'transparent',
    fontSize: 14,
    color: '#1E293B'
  },

  dropdown: {
    position: 'absolute',
    top: 45,
    width: '100%',
    background: 'white',
    border: '1px solid #E2E8F0',
    borderRadius: 8,
    maxHeight: 250,
    overflowY: 'auto',
    zIndex: 999,
    boxShadow: '0 4px 12px rgba(0,0,0,0.08)'
  },

  resultItem: {
    padding: 12,
    cursor: 'pointer',
    borderBottom: '1px solid #F1F5F9',
    transition: 'background 0.2s'
  },

  main: { 
    flex: 1, 
    display: 'flex', 
    flexDirection: 'column' 
  },

